fn test_agreement_must_beat_incumbent_votes() {
    crate::testport::assert_eq(of_rule(1, 0, 0, 0, 0, 2, 2, 700, 700), 0, "vote tie keeps incumbent");
    crate::testport::assert_eq(of_rule(1, 0, 0, 0, 0, 2, 1, 700, 700), 1, "strictly more agreeing readings");
}
#[test]
fn test_single_reading_replacement_needs_margin_300() {
    crate::testport::assert_eq(of_rule(1, 1, 0, 1, 0, 1, 0, 899, 600), 0, "299 keeps");
    crate::testport::assert_eq(of_rule(1, 1, 0, 1, 0, 1, 0, 900, 600), 2, "300 replaces");
}
#[test]
fn test_insertion_needs_confidence_700() {
    crate::testport::assert_eq(of_rule(0, 0, 0, 0, 0, 2, 0, 699, 0), 0, "agreement does not bypass insertion floor");
    crate::testport::assert_eq(of_rule(0, 0, 0, 0, 0, 2, 0, 700, 0), 3, "700 inserts");
    crate::testport::assert_eq(of_rule(0, 0, 0, 0, 1, 1, 0, 700, 0), 3, "dictionary permits single-reading alpha insertion");
    crate::testport::assert_eq(of_rule(0, 1, 0, 1, 0, 1, 0, 700, 0), 3, "format permits single-reading numeric insertion");
}
#[test]
fn test_no_deletion_even_when_all_other_readings_are_null() {
    crate::testport::assert_eq(of_rule(1, 0, 0, 0, 1, 0, 0, 1000, 0), 0, "zero candidate votes keeps the selected words");
}
#[test]
fn test_fused_copy_cannot_invent_characters() {
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let source: i32 = ow_new(words, 1, 10, 20, 110, 40, 10, 40, 110, 40, 0, 0, 123, 7, 2, 876, -1);
    let copied: i32 = of_copy(words, source, 9, 8);
    crate::testport::assert_eq(ow_get(words, copied, hd_tstart()), 123, "same recorded text span");
    crate::testport::assert_eq(ow_get(words, copied, hd_tlen()), 7, "same recorded character count");
    crate::testport::assert_eq(ow_get(words, copied, hd_conf()), 876, "same source confidence");
    crate::testport::assert_eq(ow_get(words, copied, hd_x0()), 10, "same source box");
    crate::testport::assert_eq(ow_get(words, copied, of_from()), source, "source row is explicit");
    crate::testport::assert_eq(ow_get(words, copied, owf_run()), 9, "synthetic run");
    crate::testport::assert_eq(ow_get(words, copied, hd_line()), 8, "synthetic line");
    crate::testport::assert_eq(ow_count(words), 2, "original remains for D699");
    crate::testport::assert_eq(ow_get(words, source, hd_line()), 2, "source row remains unchanged");
}
#[test]
fn test_slots_use_half_of_the_smaller_box_and_transitive_links() {
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let parents: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let sorted: &mut crate::port::Cells = &mut crate::port::Cells::new();
    ow_new(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    ow_new(words, 1, 50, 0, 150, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    ow_new(words, 1, 100, 0, 200, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    ow_new(words, 1, 151, 0, 251, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    crate::port::cells_push(rows, 0);
    crate::port::cells_push(rows, 1);
    crate::port::cells_push(rows, 2);
    crate::port::cells_push(rows, 3);
    of_align(words, rows, parents, sorted);
    crate::testport::assert_eq(of_root(parents, 0), of_root(parents, 2), "half-overlap chain is one slot");
    crate::testport::assert_eq(of_root(parents, 3), 3, "49 percent overlap stays separate");
}
#[test]
fn test_slots_never_link_different_pages() {
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let parents: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let sorted: &mut crate::port::Cells = &mut crate::port::Cells::new();
    ow_new(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    ow_new(words, 2, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    crate::port::cells_push(rows, 0);
    crate::port::cells_push(rows, 1);
    of_align(words, rows, parents, sorted);
    crate::testport::assert_eq(of_root(parents, 0), 0, "page one");
    crate::testport::assert_eq(of_root(parents, 1), 1, "page two");
}
#[test]
fn test_oversized_and_empty_boxes_do_not_chain_slots() {
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let parents: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let sorted: &mut crate::port::Cells = &mut crate::port::Cells::new();
    ow_new(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    ow_new(words, 1, 200, 0, 300, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    ow_new(words, 1, 0, 0, 10000, 10000, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    ow_new(words, 1, 0, 0, 0, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    crate::port::cells_push(rows, 0);
    crate::port::cells_push(rows, 1);
    crate::port::cells_push(rows, 2);
    crate::port::cells_push(rows, 3);
    of_align(words, rows, parents, sorted);
    crate::testport::assert_eq(of_root(parents, 0), 0, "first word stays independent");
    crate::testport::assert_eq(of_root(parents, 1), 1, "second word stays independent");
    crate::testport::assert_eq(of_root(parents, 2), -1, "giant box cannot bridge words");
    crate::testport::assert_eq(of_root(parents, 3), -1, "empty box is excluded");
}
#[test]
fn test_equal_box_permutation_does_not_change_slot_membership() {
    let words: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let rows: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let parents: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let sorted: &mut crate::port::Cells = &mut crate::port::Cells::new();
    ow_new(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    ow_new(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1);
    crate::port::cells_push(rows, 1);
    crate::port::cells_push(rows, 0);
    of_align(words, rows, parents, sorted);
    crate::testport::assert_eq(of_root(parents, 0), of_root(parents, 1), "reverse source order links the same source rows");
}
