#[test]
fn test_format_span_bounds_do_not_overflow_or_read_outside_recorded_text() {
    let text: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(text, 49);
    crate::testport::assert_eq(ofmt_valid(text, -1, 1), 0, "negative start");
    crate::testport::assert_eq(ofmt_valid(text, 0, 2), 0, "long span");
    crate::testport::assert_eq(ofmt_valid(text, 2147483647, 2147483647), 0, "hostile overflowing span");
    crate::testport::assert_eq(ofmt_valid(text, 0, 1), 1, "recorded digit");
}
#[test]
fn test_numeric_grammar_uses_unicode_decimal_digits() {
    let arabic: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(arabic, 1633);
    crate::port::cells_push(arabic, 1634);
    crate::port::cells_push(arabic, 46);
    crate::port::cells_push(arabic, 1637);
    crate::port::cells_push(arabic, 1632);
    crate::testport::assert_eq(ofmt_valid(arabic, 0, crate::port::cells_len(arabic)), 1, "Unicode decimal sample 1");
    let devanagari: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(devanagari, 2407);
    crate::port::cells_push(devanagari, 2408);
    crate::testport::assert_eq(ofmt_valid(devanagari, 0, crate::port::cells_len(devanagari)), 1, "Unicode decimal sample 2");
    let fullwidth: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(fullwidth, 65297);
    crate::port::cells_push(fullwidth, 65298);
    crate::testport::assert_eq(ofmt_valid(fullwidth, 0, crate::port::cells_len(fullwidth)), 1, "Unicode decimal sample 3");
    let superscript: &mut crate::port::Cells = &mut crate::port::Cells::new();
    crate::port::cells_push(superscript, 178);
    crate::testport::assert_eq(ofmt_valid(superscript, 0, crate::port::cells_len(superscript)), 0, "Unicode decimal sample 4");
}
